use hog4pilot::project::{Store,Project,SavedLook};
#[test] fn persists_and_rejects_invalid(){let path=std::env::temp_dir().join(format!("hog4pilot-test-{}.sqlite",std::process::id()));{let mut s=Store::open(&path).unwrap();let p=Project{name:"Спектакль".into(),looks:vec![SavedLook{name:"Тёплый".into(),intensity:0.5,rgb:[1.0,0.5,0.2],seconds:2.0}]};s.save(&p).unwrap();let mut bad=p.clone();bad.looks[0].intensity=2.0;assert!(s.save(&bad).is_err());}{let s=Store::open(&path).unwrap();assert_eq!(s.load().unwrap().unwrap().looks[0].intensity,0.5);}std::fs::remove_file(path).unwrap();}
